import json,pathlib
P=pathlib.Path(__file__).parent;R=P.resolve().parents[2]
def read(n):return json.loads((P/n).read_text(encoding='utf8'))
def dump(n,x):(P/n).write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n',encoding='utf8')
spans=read('reading-source.json')['source_spans'];ledger=read('reading-token-ledger.json');grammar=json.loads((R/'curriculum/grammar.json').read_text(encoding='utf8'))['features'];G={g['feature_id']:g for g in grammar}
# code, id, inclusive source-word positions, visible help, earlier relevant feature(s)
DATA=[
 ('D','orientation',1,103,'The Savior addresses a rich man. This selection contains the complete opening argument and its embedded gospel quotation. The Savior’s speech continues on the next page: the unmatched outer quotation mark is present in this bounded source selection.',[]),
 ('D','genitive-controls',7,28,'For hwȳ and tō hwon ask why. Fæsthafol governs the genitive mīnra gōda, “holding tightly to my goods”; rēcelēasodest takes genitive ðǣre giefe, “neglected the gift.” Relative ðe introduces the following clauses; long ðē is the personal pronoun “you/to you.”',['u08-relative-the']),
 ('D','future-response',29,54,'Āfierre, bist, forgielde and gesęlle have present morphology with future reference in this promised response. Noldest is “you would not/refused”; geðęncean is its infinitive. Wille expresses the present speaker’s intention even within a remembered proposition: no mechanical backshift is required.', ['u06-plain-infinitive-complement']),
 ('D','generic-agent',55,71,'Ǣghwilcum męnn is the dative recipient; āne gōde dǣd is the accusative object. The subject of gedēð is generic mann, “one/a person.” Mid hundtēontigum means “with a hundredfold.” The singular him refers back to the person.', ['u08-relative-the']),
 ('D','embedded-quotation',72,93,'Gecweden and gesǣd are two past participles with is; Cook calls the pairing pleonastic. Swā-hwæt-swā means “whatever,” the object of sęllað. Ānum of mīnum ðǣm lǣstum means “to one of my least ones”; lǣstum is substantival and dative plural. The repeated gē/sęllað address the quoted audience.', ['u07-passive','u08-relative-the']),
 ('D','exchange',94,103,'Wið ðǣm means “in return for that,” with dative singular. Drēam here means joy or bliss, not a dream. Ēcne agrees with accusative masculine drēam.',[]),
 ('P','translation',1,29,'Ælfred is subject. The feminine hīe/hēo refers to bōc. The source-language phrases use of plus dative; on Englisc gives the translation’s goal. Word be worde contrasts literal verbal correspondence with andgiet of andgiete, sense for sense. Gedōn describes the work’s resulting arrangement.', ['u02-third-person-possessors']),
 ('P','hindrances',30,68,'The two superlative adverbs mean “most clearly and most intelligibly.” For plus dative introduces the worldly cares that constrained how clearly Alfred could explain it. Ǣgðer ge ... ge means “both ... and.” On mōde/on līchaman identify mind and body. Sind is the plural present “are.” The relative ðe at word61 refers to bisga; those cares are the subject of becōmon.', ['u08-relative-the']),
 ('P','anterior-actions',69,99,'Hæfde underfangen = “had received/taken charge of.” The repeated hæfde governs both geleornod and gewęnd: “had studied ... and translated ...”. Ðēah here is “nevertheless”; ðā ... ðā frames “when ... then.” Tō Engliscum spelle and tō lēoðe mark resulting literary form. Hīe/hēo still refers to the book.', ['u12-habban-perfect','u13-correlative-clause-reference']),
 ('P','appeal',100,119,'Supply hē (Alfred) with bitt and hālsað, as Cook’s note4 directs. Ǣlcne ðāra ðe ... means “each of those who ...”. Lyste is impersonal: “whom it may please to read this book”; its understood accusative experiencer is the prospective reader. The requested ðæt clause contains subjunctive gebidde, “that he pray for him.”', ['u13-halsian-request','u14-gebiddan-subjunctive']),
 ('P','reader-author-reference',120,132,'Ne wīte continues the request: “and not blame him.” In gif hē hit rihtlicor ongiete ðonne hē meahte, the first hē is the reader and the second is Alfred (Cook’s notes6–7). Ongiete is subjunctive; wīte is the verb “blame,” not the noun “punishment.”', ['u13-halsian-request']),
 ('P','capacity',133,152,'Be ... mǣðe and be ... ǣmettan mean according to the measure of one’s understanding and one’s available leisure. Sceal governs sprecan and dōn. Both ðæt ... and ðæt-ðæt ... function as “what/that which.” Preserve the source’s hyphenated spelling in the latter.', ['u06-plain-infinitive-complement','u09-free-relative-that']),
 ('R','address',1,10,'Dryhten and God are direct address; ælmihtiga is weak singular. Wyrhta and Wealdend are “Maker and Ruler,” with genitive ealra gesceafta. This Maker sense is distinct from the previously taught workman sense.', ['u09-vocative-weak-adjective']),
 ('R','grounds-of-appeal',11,40,'The for phrases name grounds of appeal. In ðǣre hālgan rōde tācne, the genitive phrase “of the holy cross” depends on dative tācne. Sanctæ Marian and Sancti Michaeles are supplied names in genitive function with mixed foreign-name inflection; do not derive a new productive Latin paradigm. Gehīersumnesse is obedience. Hālgena means saints; lufan is the weak noun’s dative; earnungum means merits.',[]),
 ('R','guidance',41,66,'The requested ðæt clause has gewissie, “that you guide.” Bęt ðonne ic āworhte tō ðē means better than my conduct towards you has deserved. The following gewissa is a direct singular command. In mīnre sāwle ðearfe, mīnre sāwle is genitive, dependent on dative ðearfe: “for my soul’s benefit.” Cunne is first-singular subjunctive, “than I myself may know.”', ['u13-halsian-request']),
 ('R','commands',67,104,'Gestaðela, gestranga, āfierr and gescield are addressed singular commands. Establish my mind according to your will; strengthen me against the devil’s temptations; remove lust and unrighteousness; protect me against visible and invisible adversaries. The latter adjectives agree with dative plural wiðerwinnum.',[]),
 ('R','teaching-purpose',105,127,'Tǣc takes dative mē. Its following ðīnne willan is the accusative object of wyrceanne (“to do your will”), as Cook’s note7 specifies. The ðæt clause gives purpose with mæge. Tōforan eallum ðingum means above all things; the two mid phrases give manner: with pure thought and a pure body.', ['u06-infinitive-forms','u06-infinitive-government']),
 ('R','titles-and-doxology',128,160,'The final causal clause names God as Creator, Redeemer, help, comfort, trust and hope. Sīe is an optative wish, “may there be”; ðē is dative. Ā is repeated three times, followed by tō worulde būtan ǣghwilcum ęnde, “for ever without any end.”', ['u07-wish-exhortation'])]
features=[];supports=[]
for code,key,lo,hi,text,prior in DATA:
 span=spans[{'D':0,'P':1,'R':2}[code]];sid=span['source_span_id'];fid='u15-source-'+code.lower()+'-'+key;hid='U15-READ-'+code+'-'+key.upper();ev=['U15-FB-P'+str(span['printed_pages'][0])]
 refs=[]
 for x in prior:
  g=G[x];refs.append(dict(feature_id=x,production_taught_in=g.get('production_taught_in'),recognition_taught_in=g.get('recognition_taught_in'),scope_note='Only the actual earlier recorded scope is prior; the detailed new passage application remains locally supplied.'))
 feat=dict(feature_id=fid,title=text.split('.')[0],description=text,knowledge_status='supplied',teaching_ids=[],evidence_refs=ev,source_span_id=sid,token_range_one_based=[lo,hi],prior_related_features=refs,scope_note='Exact passage orientation; not a productive generalization beyond the supplied sentence.')
 features.append(feat);supports.append(dict(support_id=hid,kind='construction_help',feature_ids=[fid],source_span_id=sid,token_range_one_based=[lo,hi],text=text,evidence_refs=ev,origin_category='new teaching material explaining exact source'))
 for r in ledger['tokens']:
  if r['source_span_id']==sid and lo<=r['token_index_one_based']<=hi:r['feature_ids'].append(fid);r.setdefault('support_ids',[]).append(hid)
sup=read('source-support-records.json');sup['features']=features;dump('source-support-records.json',sup)
help=read('reading-support.json');help['grammar_help']=supports;dump('reading-support.json',help)
dump('reading-token-ledger.json',ledger)
dump('reading-constructions.json',dict(schema_version=1,constructions=supports,feature_records=features,method='Each modern explanation is separate from the exact retained original apparatus. Earlier related features have been read from the actual active grammar register.'))
print(dict(construction_supports=len(supports),supplied_features=len(features)))
